type Props={route:RouteDefinition;data:WorkspaceData|null;role:Role;reload():void;params:RouteParams;user:User};
const dt=(value:string)=>new Date(value).toLocaleString('vi-VN',{hour12:false});
const message=(e:unknown)=>e instanceof Error?e.message:'Chưa thể hoàn tất yêu cầu.';
