    await writer.waitForIdle();const check=await adapter.assessment.reconcileSubmission({...t});if(!alive.current)return;
    if(check.state==='CONFIRMED'){receiptNav();return;}
    if(check.state==='UNKNOWN'){setOperationId(check.operationId);setError('Chưa xác định được kết quả nộp. Hãy kiểm tra trạng thái.');return;}
